14	)
15	
16	const (
17		codeInvalidInput = "InvalidArtifactInputError"
18		codeConflict     = "ArtifactConflictError"
19		codeNotFound     = "ArtifactNotFoundError"
20		codeStorage      = "storage_unavailable"
21	)
22	
23	var (
24		digestPattern   = regexp.MustCompile(`^sha256:[0-9a-f]{64}$`)
25		errInvalidInput = errors.New("invalid artifact input")
26	)
27	
28	// artifactInput is a registration request after normalization and validation.
29	type artifactInput struct {
30		repository        string
31		digest            string
32		tag               string
33		signatureVerified bool
34		retentionDays     int64
35		sizeBytes         int64
36	}
37	
38	func writeError(c *gin.Context, status int, code, message string) {
39		c.JSON(status, gin.H{"error": gin.H{"code": code, "message": message}})
40	}
41	
42	func artifactResponse(a service.Artifact) gin.H {
43		return gin.H{
44			"repository":         a.Repository,
45			"digest":             a.Digest,
46			"tag":                a.Tag,
47			"signature_verified": a.SignatureVerified,
48			"retention_days":     a.RetentionDays,
49			"size_bytes":         a.SizeBytes,
50			"pushed_at":          a.PushedAt,
51		}
52	}
53	
54	// decodeArtifactInput reads exactly one JSON object and validates every required
55	// field. Unknown fields are ignored; any deviation yields errInvalidInput.
56	func decodeArtifactInput(body io.Reader) (artifactInput, error) {
57		var input artifactInput
58		decoder := json.NewDecoder(body)
59		var raw map[string]json.RawMessage
60		if err := decoder.Decode(&raw); err != nil || raw == nil {
61			return input, errInvalidInput
62		}
63		if err := decoder.Decode(&struct{}{}); err != io.EOF {
64			return input, errInvalidInput
65		}
66	
67		repository, err := requiredString(raw, "repository")
68		if err != nil {
69			return input, err
70		}
71		if input.repository = strings.TrimSpace(repository); input.repository == "" {
72			return input, errInvalidInput
73		}
74	
75		tag, err := requiredString(raw, "tag")
76		if err != nil {
77			return input, err
78		}
79		if input.tag = strings.TrimSpace(tag); input.tag == "" {
80			return input, errInvalidInput
81		}
82	
83		digest, err := requiredString(raw, "digest")
84		if err != nil {
85			return input, err
86		}
87		if !digestPattern.MatchString(digest) {
88			return input, errInvalidInput
89		}
90		input.digest = digest
91	
92		if input.signatureVerified, err = requiredBool(raw, "signature_verified"); err != nil {
93			return input, err
94		}
95	
96		if input.retentionDays, err = requiredInt(raw, "retention_days"); err != nil {
97			return input, err
98		}
99		if input.retentionDays < 1 || input.retentionDays > 3650 {
100			return input, errInvalidInput
101		}
102	
103		if input.sizeBytes, err = requiredInt(raw, "size_bytes"); err != nil {
104			return input, err
105		}
106		if input.sizeBytes < 0 {
107			return input, errInvalidInput
108		}
109		return input, nil
110	}
111	
112	// isJSONNull reports an explicit JSON null. encoding/json unmarshals null
113	// into any Go value without an error and leaves the zero value behind, which
114	// would silently turn a null signature_verified into false and a null
115	// size_bytes into 0; a required field must reject null like a missing key.
116	func isJSONNull(field json.RawMessage) bool {
117		return string(field) == "null"
118	}
119	
120	func requiredString(raw map[string]json.RawMessage, name string) (string, error) {
121		field, ok := raw[name]
122		if !ok || isJSONNull(field) {
123			return "", errInvalidInput
124		}
125		var value string
126		if err := json.Unmarshal(field, &value); err != nil {
127			return "", errInvalidInput
128		}
129		return value, nil
130	}
131	
132	func requiredBool(raw map[string]json.RawMessage, name string) (bool, error) {
133		field, ok := raw[name]
134		if !ok || isJSONNull(field) {
135			return false, errInvalidInput
136		}
137		var value bool
138		if err := json.Unmarshal(field, &value); err != nil {
139			return false, errInvalidInput
140		}
141		return value, nil
142	}
143	
144	// requiredInt rejects fractional, exponential and string forms because
145	// encoding/json refuses to unmarshal them into an integer.
146	func requiredInt(raw map[string]json.RawMessage, name string) (int64, error) {
147		field, ok := raw[name]
148		if !ok || isJSONNull(field) {
149			return 0, errInvalidInput
150		}
151		var value int64
152		if err := json.Unmarshal(field, &value); err != nil {
153			return 0, errInvalidInput
154		}
155		return value, nil
156	}
157	
158	func registerArtifact(svc *service.Service) gin.HandlerFunc {
159		return func(c *gin.Context) {
160			input, err := decodeArtifactInput(c.Request.Body)
161			if err != nil {
162				writeError(c, http.StatusBadRequest, codeInvalidInput, "request body is not a valid artifact registration")
163				return
164			}
165	
166			result, err := svc.Register(service.RegisterInput{
167				Repository:        input.repository,
168				Digest:            input.digest,
169				Tag:               input.tag,
170				SignatureVerified: input.signatureVerified,
171				RetentionDays:     input.retentionDays,
172				SizeBytes:         input.sizeBytes,
173			})
174			switch {
175			case errors.Is(err, service.ErrConflict):
176				writeError(c, http.StatusConflict, codeConflict, "an artifact with this repository and digest already exists with different content")
177			case err != nil:
178				writeError(c, http.StatusServiceUnavailable, codeStorage, "database is not available")
179			default:
180				// First registrations and identical retries share the public 201;
181				// the created/duplicate distinction stays inside the service result.
182				c.JSON(http.StatusCreated, artifactResponse(result.Artifact))
183			}
184		}
185	}
186	
187	func queryArtifacts(svc *service.Service) gin.HandlerFunc {
188		return func(c *gin.Context) {
189			repository := strings.TrimSpace(c.Query("repository"))
190			tag, hasTag := c.GetQuery("tag")
191			tag = strings.TrimSpace(tag)
192			digest, hasDigest := c.GetQuery("digest")
193	
194			if repository == "" || (hasTag && hasDigest) ||
195				(hasTag && tag == "") || (hasDigest && !digestPattern.MatchString(digest)) {
196				writeError(c, http.StatusBadRequest, codeInvalidInput, "query parameters are not valid")
197				return
198			}
199	
200			query := service.Query{Repository: repository}
201			switch {
202			case hasTag:
203				query.Kind = service.QueryByTag
204				query.Tag = tag
205			case hasDigest:
206				query.Kind = service.QueryByDigest
207				query.Digest = digest
208			default:
209				query.Kind = service.QueryByRepository
210			}
211	
212			artifacts, err := svc.Query(query)
213			switch {
214			case errors.Is(err, service.ErrNotFound):
215				writeError(c, http.StatusNotFound, codeNotFound, "no artifact matches this query")
216			case err != nil:
217				writeError(c, http.StatusServiceUnavailable, codeStorage, "database is not available")
218			default:
219				response := make([]gin.H, 0, len(artifacts))
220				for _, record := range artifacts {
221					response = append(response, artifactResponse(record))
222				}
223				c.JSON(http.StatusOK, gin.H{"artifacts": response})
224			}
225		}
226	}
