1	package service_test
2	
3	import (
4		"errors"
5		"path/filepath"
6		"testing"
7	
8		"github.com/Bob-xisuke/orb-registry-catalog/internal/service"
9		"github.com/Bob-xisuke/orb-registry-catalog/internal/store"
10	)
11	
12	const (
13		sqliteDigestA = "sha256:" + "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"
14		sqliteDigestB = "sha256:" + "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb"
15	)
16	
17	// newSQLiteService opens a real SQLite file and wires the bundled adapter into
18	// a business Service through the service.Store port, returning the handle so
19	// tests can close or reopen the same file.
20	func newSQLiteService(t *testing.T) (*service.Service, *store.Store, string) {
21		t.Helper()
22		path := filepath.Join(t.TempDir(), "service.db")
23		st, err := store.Open(path)
24		if err != nil {
25			t.Fatalf("open store: %v", err)
26		}
27		return service.New(st), st, path
28	}
29	
30	func sqliteValidInput(repo, digest, tag string) service.RegisterInput {
31		return service.RegisterInput{
32			Repository:        repo,
33			Digest:            digest,
34			Tag:               tag,
35			SignatureVerified: true,
36			RetentionDays:     30,
37			SizeBytes:         1024,
38		}
39	}
40	
41	// TestSQLiteRegisterAndQuery drives registration plus all three query kinds
42	// through the business layer against the real adapter, including the
43	// created/duplicate distinction and the tag pointer that moves only on a new
44	// record.
45	func TestSQLiteRegisterAndQuery(t *testing.T) {
46		svc, st, _ := newSQLiteService(t)
47		t.Cleanup(func() { st.Close() })
48	
49		inputA := sqliteValidInput("team/app", sqliteDigestA, "latest")
50		inputB := sqliteValidInput("team/app", sqliteDigestB, "latest")
51		inputB.SizeBytes = 2048
52	
53		first, err := svc.Register(inputA)
54		if err != nil {
55			t.Fatalf("register A: %v", err)
56		}
57		if first.Outcome != service.OutcomeCreated {
58			t.Fatalf("first outcome = %v, want OutcomeCreated", first.Outcome)
59		}
60	
61		if _, err := svc.Register(inputB); err != nil {
62			t.Fatalf("register B: %v", err)
63		}
64	
65		retry, err := svc.Register(inputA)
66		if err != nil {
67			t.Fatalf("retry A: %v", err)
68		}
69		if retry.Outcome != service.OutcomeDuplicate || retry.Artifact.PushedAt != first.Artifact.PushedAt {
70			t.Fatalf("retry A = %+v, want duplicate with original pushed_at", retry)
71		}
72	
73		list, err := svc.Query(service.Query{Kind: service.QueryByRepository, Repository: "team/app"})
74		if err != nil {
75			t.Fatalf("list: %v", err)
76		}
